// Model of LockService + Resource over a CAS store (lock record: issued, holder, token, expiry).
type LockRec = (issued: int, holder: int, token: int, expiry: int); // holder -1 = none
event eLoad: (from: machine);
event eLoadR: (ver: int, rec: LockRec);
event eCas: (from: machine, ver: int, rec: LockRec);
event eCasR: (ok: bool);
event eGranted: (client: int, now: int, token: int); // token 0 = None
event eWrite: (token: int, ok: bool);

// Contract: granted tokens strictly increase; no two clients hold overlapping live leases.
spec Fencing observes eGranted {
  var last: int; var holder: int; var expiry: int; var tok: int;
  start state S {
    on eGranted do (p: (client: int, now: int, token: int)) {
      if (p.token == 0) {
        assert holder != -1 && holder != p.client && p.now < expiry, "refused while free";
      } else if (holder == p.client && p.now < expiry) {
        assert p.token == tok, "must return same token";
      } else {
        assert p.token > last, "token not increasing";
        assert holder == -1 || p.now >= expiry || holder == p.client, "granted while held";
        last = p.token; holder = p.client; expiry = p.now + 10; tok = p.token;
      }
    }
  }
  fun init() { holder = -1; }
}

machine Store {
  var ver: int; var rec: LockRec;
  start state Run {
    entry { rec = (issued = 0, holder = -1, token = 0, expiry = 0); }
    on eLoad do (p: (from: machine)) { send p.from, eLoadR, (ver = ver, rec = rec); }
    on eCas do (p: (from: machine, ver: int, rec: LockRec)) {
      if (p.ver == ver) { ver = ver + 1; rec = p.rec; send p.from, eCasR, (ok = true,); }
      else { send p.from, eCasR, (ok = false,); }
    }
  }
}

machine Client {
  var id: int;
  start state Run {
    entry (a: (s: Store, id: int)) {
      var r: LockRec; var v: int; var done: bool; var now: int; var tok: int; var ok: bool;
      id = a.id; now = choose(3) * 4;
      while (!done) {
        send a.s, eLoad, (from = this,);
        receive { case eLoadR: (p: (ver: int, rec: LockRec)) { v = p.ver; r = p.rec; } }
        if (r.holder != -1 && now < r.expiry) {
          if (r.holder == id) { tok = r.token; } else { tok = 0; }
          done = true;
        } else {
          tok = r.issued + 1;
          send a.s, eCas, (from = this, ver = v, rec = (issued = tok, holder = id, token = tok, expiry = now + 10));
          receive { case eCasR: (c: (ok: bool)) { ok = c.ok; } }
          done = ok;
        }
      }
      announce eGranted, (client = id, now = now, token = tok);
    }
  }
}

machine Main {
  start state Init {
    entry { var s: Store; s = new Store(); new Client((s = s, id = 1)); new Client((s = s, id = 2)); }
  }
}
test tcAcquire [main=Main]: assert Fencing in { Main, Store, Client };
EOF
